// ============================================================
// MERGE REPORT DATA - n8n Code Node (Multi-Campaign)
// Runs once for all items, outputs one item per matched campaign
// ============================================================
const config = $('Workflow Configuration').item.json;
const clientName = config.clientName || 'Unknown Client';
const startDate = config.startDate || '';
const endDate = config.endDate || '';
const campaignContext = config.campaignContext || '';

// Filters change logs down to the ones relevant to a specific campaign.
// Logs without a campaign_name are treated as client-wide and pass through to every campaign.
function filterLogsByCampaign(logs, campaignName) {
  if (!campaignName || !logs.length) return logs;
  const norm = n => (n || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const cn = norm(campaignName);
  return logs.filter(log => {
    if (!log.campaign_name) return true;
    const ln = norm(log.campaign_name);
    return ln === cn || cn.includes(ln) || ln.includes(cn);
  });
}

// Index analytics by campaign_id
const analyticsMap = {};
try {
  $('Get Campaign Analytics').all().forEach(item => {
    const id = item.json.campaign_id;
    if (id) analyticsMap[id] = item.json;
  });
} catch(e) {}

// Index matched campaign data by id
const campaignDataMap = {};
try {
  $('Get matched campaign data').all().forEach(item => {
    const id = item.json.id;
    if (id) campaignDataMap[id] = item.json;
  });
} catch(e) {}

// Index aggregated lead stats by campaign_id (memory-safe: counts + repliers only)
const leadsAggMap = {};
try {
  $('Accumulate Leads').all().forEach(item => {
    const j = item.json || {};
    if (j.campaignId) {
      leadsAggMap[j.campaignId] = {
        totalLeads: j.totalLeads || 0,
        withReplies: j.withReplies || []
      };
    }
  });
} catch(e) {}

// Accounts are shared - get all once
let allAccounts = [];
try {
  const rawAccounts = $('Get all accounts').first().json;
  allAccounts = rawAccounts.items || [];
} catch(e) {}

// Index replies by campaign_id
const repliesMap = {};
try {
  $('Get Campaign Replies').all().forEach(item => {
    const emails = item.json.emails || item.json.items || item.json.data || [];
    emails.forEach(e => {
      const cid = e.campaign_id || e.campaign;
      if (!cid) return;
      if (!repliesMap[cid]) repliesMap[cid] = [];
      repliesMap[cid].push(e);
    });
  });
} catch(e) {}

// Index lifetime analytics by campaign_id
const lifetimeMap = {};
try {
  $('Get Lifetime Campaign Analytics').all().forEach(item => {
    const id = item.json.campaign_id;
    if (id) lifetimeMap[id] = item.json;
  });
} catch(e) {}

// Get all matched campaigns
const matchedCampaigns = $('Match Instantly Campaign Name - Exist or not').all()
  .filter(item => item.json.matched === true);

// Index campaign change logs by client
let changeLogs = [];
try {
  changeLogs = $('Fetch Campaign Change Logs').all().map(item => item.json);
} catch(e) {}

// Prior messaging knowledge base entries for this client (cross-campaign, cross-platform learnings)
let messagingKb = [];
try {
  messagingKb = $('Normalize Messaging KB').all()
    .map(item => item.json)
    .filter(e => e && !e.is_empty_kb);
} catch(e) {}

const results = [];

for (const matchItem of matchedCampaigns) {
  const matchData = matchItem.json;
  const campaignId = matchData.matchedCampaignId;
  const targetCampaignName = matchData.targetCampaignName;

  const campaignData = campaignDataMap[campaignId] || matchData.matchedCampaign || {};
  const analyticsData = analyticsMap[campaignId] || {};
  const leadsAgg = leadsAggMap[campaignId] || { totalLeads: 0, withReplies: [] };
  const replies = repliesMap[campaignId] || [];

  const campaignChangeLogs = filterLogsByCampaign(changeLogs, targetCampaignName);
  const contextLog = campaignChangeLogs.find(log => log.change_category === 'Campaign Context');
  const activeContext = contextLog ? (contextLog.change_description || '') : '';
  const requestContext = { clientName, startDate, endDate, campaignContext: activeContext || campaignContext, targetCampaignName };

const leadsAnalysis = { totalLeads: leadsAgg.totalLeads, withReplies: leadsAgg.withReplies };

const accounts = allAccounts;
const campaignEmailList = campaignData.email_list || [];
const campaignAccounts = accounts.filter(acc => campaignEmailList.includes(acc.email));
const accountsAnalysis = { totalInCampaign: campaignAccounts.length, totalAvailable: accounts.length, averageWarmupScore: 0, byStatus: {}, healthySenders: [], problemSenders: [] };
let warmupScoreSum = 0, warmupScoreCount = 0;
campaignAccounts.forEach(account => {
  if (account.stat_warmup_score !== undefined) { warmupScoreSum += account.stat_warmup_score; warmupScoreCount++; }
  const status = account.status === 1 ? 'Active' : 'Inactive';
  accountsAnalysis.byStatus[status] = (accountsAnalysis.byStatus[status] || 0) + 1;
  const senderInfo = { email: account.email, name: `${account.first_name} ${account.last_name}`, warmupScore: account.stat_warmup_score || 0, status: account.status, dailyLimit: account.daily_limit };
  if (account.stat_warmup_score >= 100 && account.status === 1) { accountsAnalysis.healthySenders.push(senderInfo); } else { accountsAnalysis.problemSenders.push(senderInfo); }
});
accountsAnalysis.averageWarmupScore = warmupScoreCount > 0 ? Math.round(warmupScoreSum / warmupScoreCount) : 0;

const creationTs = new Date(campaignData.timestamp_created || 0).getTime();
const endTs = new Date(config.endDate || new Date()).getTime();
const ageDays = creationTs > 0 ? Math.round((endTs - creationTs) / (1000 * 60 * 60 * 24)) : 999;

const campaignConfig = { name: campaignData.name, id: campaignData.id, status: campaignData.status, statusText: ['Draft','Active','Paused','Completed'][campaignData.status] || 'Unknown', createdAt: campaignData.timestamp_created, campaignAgeDays: ageDays, sequences: campaignData.sequences, senderCount: campaignData.email_list?.length || 0, openTracking: campaignData.open_tracking, linkTracking: campaignData.link_tracking };

const analytics = analyticsData;
const calculatedMetrics = {
  replyRate: analytics.emails_sent_count > 0 ? ((analytics.reply_count_unique / analytics.emails_sent_count) * 100).toFixed(2) : 0,
  bounceRate: analytics.emails_sent_count > 0 ? ((analytics.bounced_count / analytics.emails_sent_count) * 100).toFixed(2) : 0,
  autoReplyRate: analytics.emails_sent_count > 0 ? ((analytics.reply_count_automatic / analytics.emails_sent_count) * 100).toFixed(2) : 0,
  emailsPerLead: analytics.leads_count > 0 ? (analytics.emails_sent_count / analytics.leads_count).toFixed(2) : 0
};

// Find the latest historical snapshot for this campaign
let previousSnapshot = null;
try {
  const rawHistory = $('Normalize Client History').all();
  const history = rawHistory.map(item => item.json).flat().filter(Boolean);
  previousSnapshot = history.find(h => 
    h.campaign_id === campaignId && 
    h.reporting_window_end < startDate &&
    h.platform === 'instantly'
  ) || null;
} catch(e) {}

const reportData = { requestContext, campaignConfig, analytics: { ...analytics, calculated: calculatedMetrics }, leadsAnalysis: { totalLeads: leadsAnalysis.totalLeads, leadsWithReplies: leadsAnalysis.withReplies }, accountsAnalysis, previousSnapshot, changeLogs: campaignChangeLogs, priorMessagingContext: messagingKb, generatedAt: new Date().toISOString() };

let replyHighlights = [];
try {
  const emails = replies;
  const startTs = requestContext.startDate ? new Date(requestContext.startDate).getTime() : 0;
  const endTs = requestContext.endDate ? new Date(requestContext.endDate).getTime() + 86400000 : Infinity;
  const filtered = emails.filter(e => {
    const ts = new Date(e.timestamp_email || e.timestamp_created || e.created_at || 0).getTime();
    const inWindow = ts >= startTs && ts <= endTs;
    if (!inWindow) return false;

    // Exclude if Instantly auto-reply flags are true
    if (e.is_auto === true || e.is_auto_reply === true || e.auto === true || e.auto_reply === true) {
      return false;
    }

    // Exclude by subject/body out-of-office keywords
    const subject = (e.subject || '').toLowerCase();
    const body = (e.body?.text || e.body_text || e.text_body || e.snippet || '').toLowerCase();

    const isOOO = subject.includes('out of office') || 
                  subject.includes('automatic reply') || 
                  subject.includes('autoreply') ||
                  subject.includes('vacation response') ||
                  body.includes('out of office') || 
                  body.includes('automatic response') || 
                  body.includes('auto-response') ||
                  body.includes('autoreply');

    return !isOOO;
  });
  replyHighlights = filtered.map(e => ({ from: e.from_address_email || e.from_address || e.from || '', subject: e.subject || '', body: (e.body?.text || e.body_text || e.text_body || e.snippet || '').slice(0, 1500), timestamp: e.timestamp || e.timestamp_created || e.created_at || '' }));
} catch(err) { replyHighlights = []; }
reportData.replyHighlights = replyHighlights;

  results.push({ json: { reportData, reportDataString: JSON.stringify(reportData, null, 2) } });
}

return results;

// ============================================================
// MATCH INSTANTLY CAMPAIGNS - Auto-discover active campaigns
// ============================================================
const campaigns = $json.items ?? $json.data ?? (Array.isArray($json) ? $json : []);
const results = [];
const activeCampaigns = campaigns.filter(c => c.status === 1);
for (const c of activeCampaigns) {
  results.push({ json: { targetCampaignName: c.name, matched: true, matchedCampaignName: c.name, matchedCampaignId: c.id, matchedCampaign: c } });
}
if (results.length === 0) { results.push({ json: { targetCampaignName: null, matched: false, matchedCampaignName: null, matchedCampaignId: null, matchedCampaign: null } }); }
return results;

// ============================================================
// MATCH HEYREACH CAMPAIGNS - Auto-discover active campaigns
// ============================================================
const campaigns = $json.items ?? $json.data ?? (Array.isArray($json) ? $json : []);
const results = [];
const activeCampaigns = campaigns.filter(c => c.status === 'IN_PROGRESS' || c.status === 'active' || c.status === 1 || c.isActive === true);
for (const c of activeCampaigns) {
  results.push({ json: { targetCampaignName: c.name || c.title, matched: true, matchedCampaignName: c.name || c.title, matchedCampaignId: c.id, matchedCampaign: c } });
}
if (results.length === 0) { results.push({ json: { targetCampaignName: null, matched: false, matchedCampaignName: null, matchedCampaignId: null, matchedCampaign: null } }); }
return results;

// ============================================================
// HEYREACH MERGE REPORT DATA (Multi-Campaign)
// Runs once for all items, outputs one item per matched campaign
// ============================================================
const config = $('Workflow Configuration').item.json;

// Filters change logs down to the ones relevant to a specific campaign.
// Logs without a campaign_name are treated as client-wide and pass through to every campaign.
function filterLogsByCampaign(logs, campaignName) {
  if (!campaignName || !logs.length) return logs;
  const norm = n => (n || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const cn = norm(campaignName);
  return logs.filter(log => {
    if (!log.campaign_name) return true;
    const ln = norm(log.campaign_name);
    return ln === cn || cn.includes(ln) || ln.includes(cn);
  });
}

// Index campaign data by campaign id
const campaignDataMap = {};
try {
  $('Retrieve found campaign data').all().forEach(item => {
    const id = item.json.id;
    if (id) campaignDataMap[id] = item.json;
  });
} catch(e) {}

// Index stats by campaign id using paired item
const statsMap = {};
try {
  const allStatsItems = $('Retrieve overall statistics for found campaign').all();
  allStatsItems.forEach(item => {
    const pairedInput = item.pairedItem;
    if (pairedInput !== undefined) {
      const inputItem = $('Wait - HeyReach API').all()[pairedInput.item];
      const campaignId = inputItem.json.matchedCampaignId;
      if (campaignId) {
        statsMap[campaignId] = item.json;
      }
    }
  });
} catch(e) {}

// Get LinkedIn accounts (shared)
let accountsData = [];
try {
  const rawAccounts = $('Retrieve all LinkedIn accounts').first().json;
  accountsData = rawAccounts.items || (Array.isArray(rawAccounts) ? rawAccounts : []);
} catch(e) {}

// Index inbox conversations by campaign id using paired item
const inboxMap = {};
try {
  const allInboxItems = $('Retrieve inbox messages for found campaign').all();
  allInboxItems.forEach(item => {
    const pairedInput = item.pairedItem;
    if (pairedInput !== undefined) {
      const inputItem = $('Wait - HeyReach API').all()[pairedInput.item];
      const campaignId = inputItem.json.matchedCampaignId;
      if (campaignId) {
        inboxMap[campaignId] = item.json.items || [];
      }
    }
  });
} catch(e) {}

// Get all matched HeyReach campaigns
const matchedCampaigns = $('Match Heyreach Campaign Name - Exist or not').all()
  .filter(item => item.json.matched === true);

// Index campaign change logs by client
let changeLogs = [];
try {
  changeLogs = $('Fetch Campaign Change Logs').all().map(item => item.json);
} catch(e) {}

// Prior messaging knowledge base entries for this client (cross-campaign, cross-platform learnings)
let messagingKb = [];
try {
  messagingKb = $('Normalize Messaging KB').all()
    .map(item => item.json)
    .filter(e => e && !e.is_empty_kb);
} catch(e) {}

const results = [];

for (let idx = 0; idx < matchedCampaigns.length; idx++) {
  const matchData = matchedCampaigns[idx].json;
  const campaignId = matchData.matchedCampaignId;

  const campaignChangeLogs = filterLogsByCampaign(changeLogs, matchData.targetCampaignName);
  const contextLog = campaignChangeLogs.find(log => log.change_category === 'Campaign Context');
  const activeContext = contextLog ? (contextLog.change_description || '') : '';
  const requestContext = {
    clientName: config.clientName,
    campaignContext: activeContext || config.campaignContext,
    startDate: config.startDate,
    endDate: config.endDate,
    targetCampaignName: matchData.targetCampaignName,
    platformName: 'HeyReach'
  };

  let campaignData = campaignDataMap[campaignId] || matchData.matchedCampaign || matchData;

  // Stats: try by campaignId match
  let statsData = statsMap[campaignId] || { overallStats: {}, byDayStats: {} };

  const inboxData = inboxMap[campaignId] || [];

const creationTs = new Date(campaignData.creationTime || 0).getTime();
const endTs = new Date(config.endDate || new Date()).getTime();
const ageDays = creationTs > 0 ? Math.round((endTs - creationTs) / (1000 * 60 * 60 * 24)) : 999;

const campaignConfig = { id: campaignData.id || matchData.matchedCampaignId, name: campaignData.name || matchData.matchedCampaignName, status: campaignData.status || 'Unknown', creationTime: campaignData.creationTime, campaignAgeDays: ageDays, senderAccountIds: campaignData.campaignAccountIds || [], senderCount: (campaignData.campaignAccountIds || []).length, progressStats: campaignData.progressStats || { totalUsers: 0, totalUsersInProgress: 0, totalUsersPending: 0, totalUsersFinished: 0, totalUsersFailed: 0, totalUsersManuallyStopped: 0, totalUsersExcluded: 0 } };

const overallStats = statsData.overallStats || {};
const analytics = { connectionsSent: overallStats.connectionsSent || 0, connectionsAccepted: overallStats.connectionsAccepted || 0, profileViews: overallStats.profileViews || 0, messagesSent: overallStats.totalMessageStarted || overallStats.messagesSent || 0, totalMessageStarted: overallStats.totalMessageStarted || 0, totalMessageReplies: overallStats.totalMessageReplies || 0, inmailMessagesSent: overallStats.inmailMessagesSent || 0, totalInmailStarted: overallStats.totalInmailStarted || 0, totalInmailReplies: overallStats.totalInmailReplies || 0, connectionAcceptanceRate: overallStats.connectionAcceptanceRate ? (overallStats.connectionAcceptanceRate * 100).toFixed(2) : '0.00', messageReplyRate: overallStats.messageReplyRate ? (overallStats.messageReplyRate * 100).toFixed(2) : '0.00', totalLeads: campaignConfig.progressStats.totalUsers, leadsFinished: campaignConfig.progressStats.totalUsersFinished, leadsFailed: campaignConfig.progressStats.totalUsersFailed, leadsInProgress: campaignConfig.progressStats.totalUsersInProgress, leadsPending: campaignConfig.progressStats.totalUsersPending, leadsExcluded: campaignConfig.progressStats.totalUsersExcluded };

const campaignAccountIds = campaignConfig.senderAccountIds;
const accountsAnalysis = { totalAccountsInCampaign: campaignAccountIds.length, accounts: [], activeCount: 0 };
accountsData.forEach(account => {
  if (campaignAccountIds.includes(account.id)) {
    if (account.isActive === true) accountsAnalysis.activeCount++;
    accountsAnalysis.accounts.push({ id: account.id, name: `${account.firstName || ''} ${account.lastName || ''}`.trim(), email: account.emailAddress, isActive: account.isActive, authIsValid: account.authIsValid });
  }
});

const sentimentKeywords = { positive: ['interested','yes','sure','love to','sounds good','happy to','schedule','call','meeting','tell me more','send more','great','perfect','excited','looking forward','thanks for reaching','keep me posted','next one'], negative: ['not interested','no thanks','no thank you','remove','stop','unsubscribe','spam','wrong person'], neutral: ['not now','bad timing','busy','maybe later','check back','next quarter'] };
function classifySentiment(text) {
  if (!text) return 'informational';
  const l = text.toLowerCase();
  for (const k of sentimentKeywords.positive) if (l.includes(k)) return 'positive';
  for (const k of sentimentKeywords.negative) if (l.includes(k)) return 'negative';
  for (const k of sentimentKeywords.neutral) if (l.includes(k)) return 'neutral';
  return 'informational';
}

const windowStartTs = requestContext.startDate ? new Date(requestContext.startDate).getTime() : 0;
const windowEndTs = requestContext.endDate ? new Date(requestContext.endDate).getTime() + 86400000 : Infinity;
const replyAnalysis = { totalConversations: inboxData.length, conversationsWithReplies: 0, totalReplies: 0, replies: [], sentimentBreakdown: { positive: [], neutral: [], negative: [], informational: [] } };
const leadsAnalysis = { totalLeads: analytics.totalLeads, byJobTitle: {}, byCompany: {}, connectedLeads: [], repliedLeads: [] };

inboxData.forEach(conversation => {
  const profile = conversation.correspondentProfile || {};
  const leadInfo = {
    name: `${profile.firstName || ''} ${profile.lastName || ''}`.trim(),
    company: profile.companyName || '',
    position: profile.headline || profile.position || '',
    location: profile.location || '',
    linkedInUrl: profile.profileUrl || ''
  };

  const lastSender = conversation.lastMessageSender || '';
  const lastMsgAt  = conversation.lastMessageAt || conversation.lastMessageTime || '';
  const lastMsgText = conversation.lastMessageText || '';
  const lastTs = lastMsgAt ? new Date(lastMsgAt).getTime() : 0;

  // Reply in window: correspondent replied AND that message falls in the window
  if (lastSender === 'CORRESPONDENT' && lastTs >= windowStartTs && lastTs <= windowEndTs) {
    replyAnalysis.conversationsWithReplies++;
    replyAnalysis.totalReplies += 1;
    const sentiment = classifySentiment(lastMsgText);
    const replyRecord = {
      from: leadInfo.name,
      company: leadInfo.company,
      position: leadInfo.position,
      linkedInUrl: leadInfo.linkedInUrl,
      replyText: lastMsgText,
      replyPreview: lastMsgText.length > 300 ? lastMsgText.substring(0, 300) + '...' : lastMsgText,
      timestamp: lastMsgAt,
      sentiment
    };
    replyAnalysis.replies.push(replyRecord);
    leadsAnalysis.repliedLeads.push(leadInfo);
    replyAnalysis.sentimentBreakdown[sentiment].push(replyRecord);
  }

  leadsAnalysis.connectedLeads.push(leadInfo);
});

if (!analytics.messagesSent || analytics.messagesSent === 0) {
  analytics.messagesSent = inboxData.length;
}

const totalRepliesForSentiment = replyAnalysis.totalReplies || 1;
replyAnalysis.sentimentSummary = { positive: { count: replyAnalysis.sentimentBreakdown.positive.length }, neutral: { count: replyAnalysis.sentimentBreakdown.neutral.length }, negative: { count: replyAnalysis.sentimentBreakdown.negative.length }, informational: { count: replyAnalysis.sentimentBreakdown.informational.length } };

// Find the latest historical snapshot for this campaign
let previousSnapshot = null;
try {
  const rawHistory = $('Normalize Client History').all();
  const history = rawHistory.map(item => item.json).flat().filter(Boolean);
  previousSnapshot = history.find(h => 
    h.campaign_id === campaignId && 
    h.reporting_window_end < config.startDate &&
    h.platform === 'heyreach'
  ) || null;
} catch(e) {}

const reportData = { requestContext, platformType: 'linkedin', campaignConfig, analytics, leadsAnalysis: { totalLeads: leadsAnalysis.totalLeads, connectedCount: leadsAnalysis.connectedLeads.length, repliedCount: leadsAnalysis.repliedLeads.length, repliedLeads: leadsAnalysis.repliedLeads }, replyAnalysis, accountsAnalysis, previousSnapshot, changeLogs: campaignChangeLogs, priorMessagingContext: messagingKb, generatedAt: new Date().toISOString() };

  results.push({ json: { reportData, reportDataString: JSON.stringify(reportData, null, 2) } });
}

return results;

// Parse structured JSON output from Instantly AI Agent — one item per campaign
const config = $('Workflow Configuration').item.json;
const allItems = $input.all();
const matchItems = $('Match Instantly Campaign Name - Exist or not').all()
  .filter(item => item.json.matched === true);

// Enforce strict output schema — fills safe defaults so downstream nodes
// never receive undefined fields or mixed window/lifetime values
function enforceInstantlySchema(d) {
  d = d || {};
  const sc = d.performanceScorecard || {};
  const hl = d.replyHighlights || {};
  const ki = d.keyInsights || {};
  const ov = d.campaignOverview || {};

  // hasReplies must be boolean true for replies to be included
  const hasReplies = hl.hasReplies === true;

  return {
    campaignName: d.campaignName || null,
    executiveSummary: typeof d.executiveSummary === 'string' ? d.executiveSummary : null,
    campaignOverview: {
      campaignName: ov.campaignName || null,
      status: ov.status || null,
      reportingWindow: ov.reportingWindow || null,
      senderAccounts: ov.senderAccounts || null
    },
    performanceScorecard: {
      // All window metrics — must be numbers; default 0, never null substituted from lifetime
      emailsSent:     typeof sc.emailsSent === 'number'    ? sc.emailsSent    : 0,
      totalLeads:     typeof sc.totalLeads === 'number'    ? sc.totalLeads    : 0,
      replyRate:      typeof sc.replyRate === 'string'     ? sc.replyRate     : '0.00%',
      bounceRate:     typeof sc.bounceRate === 'string'    ? sc.bounceRate    : '0.00%',
      openRate:       typeof sc.openRate === 'string'      ? sc.openRate      : 'Not tracked — open tracking disabled',
      autoReplyRate:  typeof sc.autoReplyRate === 'string' ? sc.autoReplyRate : '0.00%',
      emailsPerLead:  sc.emailsPerLead !== undefined       ? sc.emailsPerLead : null
    },
    replyHighlights: {
      hasReplies,
      totalReplies:       hasReplies && typeof hl.totalReplies === 'number'   ? hl.totalReplies   : 0,
      humanReplies:       hasReplies && typeof hl.humanReplies === 'number'   ? hl.humanReplies   : 0,
      sentimentBreakdown: hasReplies ? (hl.sentimentBreakdown || null)        : null,
      replies:            hasReplies && Array.isArray(hl.replies)             ? hl.replies        : []
    },
    keyInsights: {
      verdict:       ki.verdict       || null,
      primarySignal: ki.primarySignal || null,
      whatsWorking:  Array.isArray(ki.whatsWorking)  ? ki.whatsWorking  : [],
      areasToWatch:  Array.isArray(ki.areasToWatch)  ? ki.areasToWatch  : []
    }
  };
}

const results = [];
for (let i = 0; i < allItems.length; i++) {
  const raw = allItems[i].json.output || allItems[i].json.text || '';
  let parsed = {};
  let parseError = null;

  try {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      parsed = JSON.parse(match[0]);
      parsed = enforceInstantlySchema(parsed); // enforce schema on valid output
    } else {
      parseError = 'No JSON found in AI output';
    }
  } catch (e) {
    parseError = e.message;
  }

  if (parseError) {
    // Schema-safe error placeholder so downstream never breaks
    parsed = enforceInstantlySchema({ error: parseError, rawPreview: raw.slice(0, 300) });
    parsed.error = parseError;
    parsed.rawPreview = raw.slice(0, 300);
  }

  const targetCampaignName = matchItems[i]?.json.targetCampaignName || parsed.campaignName || `Campaign ${i + 1}`;

  results.push({
    json: {
      instantlyData: { ...parsed, targetCampaignName, platform: 'instantly' },
      targetCampaignName,
      clientName: config.clientName,
      startDate: config.startDate,
      endDate: config.endDate
    }
  });
}
return results;

// Parse structured JSON output from HeyReach AI Agent — one item per campaign
const config = $('Workflow Configuration').item.json;
const allItems = $input.all();
const matchItems = $('Match Heyreach Campaign Name - Exist or not').all()
  .filter(item => item.json.matched === true);

// Enforce strict output schema — fills safe defaults so downstream nodes
// never receive undefined fields or mixed window/lifetime values
function enforceHeyReachSchema(d) {
  d = d || {};
  const sc = d.performanceScorecard || {};
  const hl = d.replyHighlights || {};
  const ki = d.keyInsights || {};
  const ov = d.campaignOverview || {};

  // hasReplies must be boolean true for replies to be included
  const hasReplies = hl.hasReplies === true;

  return {
    campaignName: d.campaignName || null,
    executiveSummary: typeof d.executiveSummary === 'string' ? d.executiveSummary : null,
    campaignOverview: {
      platform:        ov.platform        || 'LinkedIn (HeyReach)',
      status:          ov.status          || null,
      reportingWindow: ov.reportingWindow || null,
      senderAccounts:  ov.senderAccounts  || null
    },
    performanceScorecard: {
      // All window metrics — must be numbers; default 0, never substituted from lifetime
      connectionRequestsSent:   typeof sc.connectionRequestsSent === 'number'   ? sc.connectionRequestsSent   : 0,
      connectionsAccepted:      typeof sc.connectionsAccepted === 'number'      ? sc.connectionsAccepted      : 0,
      connectionAcceptanceRate: typeof sc.connectionAcceptanceRate === 'string' ? sc.connectionAcceptanceRate : '0.00%',
      messagesSent:             typeof sc.messagesSent === 'number'             ? sc.messagesSent             : 0,
      messageReplies:           typeof sc.messageReplies === 'number'           ? sc.messageReplies           : 0,
      messageReplyRate:         typeof sc.messageReplyRate === 'string'         ? sc.messageReplyRate         : '0.00%',
      failureRate:              typeof sc.failureRate === 'string'              ? sc.failureRate              : '0.00%'
    },
    replyHighlights: {
      hasReplies,
      conversationsWithReplies: hasReplies && typeof hl.conversationsWithReplies === 'number' ? hl.conversationsWithReplies : 0,
      sentimentBreakdown:       hasReplies ? (hl.sentimentBreakdown || null) : null,
      replies:                  hasReplies && Array.isArray(hl.replies) ? hl.replies : []
    },
    keyInsights: {
      verdict:       ki.verdict       || null,
      primarySignal: ki.primarySignal || null,
      whatsWorking:  Array.isArray(ki.whatsWorking) ? ki.whatsWorking : [],
      areasToWatch:  Array.isArray(ki.areasToWatch) ? ki.areasToWatch : []
    }
  };
}

const results = [];
for (let i = 0; i < allItems.length; i++) {
  const raw = allItems[i].json.output || allItems[i].json.text || '';
  let parsed = {};
  let parseError = null;

  try {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      parsed = JSON.parse(match[0]);
      parsed = enforceHeyReachSchema(parsed); // enforce schema on valid output
    } else {
      parseError = 'No JSON found in AI output';
    }
  } catch (e) {
    parseError = e.message;
  }

  if (parseError) {
    // Schema-safe error placeholder so downstream never breaks
    parsed = enforceHeyReachSchema({ error: parseError, rawPreview: raw.slice(0, 300) });
    parsed.error = parseError;
    parsed.rawPreview = raw.slice(0, 300);
  }

  const targetCampaignName = matchItems[i]?.json.targetCampaignName || parsed.campaignName || `Campaign ${i + 1}`;

  results.push({
    json: {
      heyreachData: { ...parsed, targetCampaignName, platform: 'heyreach' },
      targetCampaignName,
      clientName: config.clientName,
      startDate: config.startDate,
      endDate: config.endDate
    }
  });
}
return results;

// ============================================================
// COMPOSE COMBINED REPORT — Refactored Slack layout + CSV generator
// ============================================================
const items = $input.all();
const config = $('Workflow Configuration').item.json;

const clientName = config.clientName || 'Unknown Client';
const startDate = config.startDate || '';
const endDate = config.endDate || '';

let campaignContext = config.campaignContext || '';
try {
  const logs = $('Fetch Campaign Change Logs').all().map(item => item.json);
  const contextLog = logs.find(log => log.change_category === 'Campaign Context');
  if (contextLog) {
    campaignContext = contextLog.change_description || '';
  }
} catch(e) {}

const instantlyCampaignNames = Array.isArray(config.instantlyCampaignNames) ? config.instantlyCampaignNames : [];
const heyReachCampaignNames = Array.isArray(config.heyReachCampaignNames) ? config.heyReachCampaignNames : [];

const instantlyItems = [];
const heyreachItems = [];
const instantlyLifetimeItems = [];
const heyreachLifetimeItems = [];

for (const item of items) {
  const d = item.json || {};
  if (d.instantlyData && typeof d.instantlyData === 'object' && !d.instantlyData.error) {
    instantlyItems.push(d.instantlyData);
  }
  if (d.heyreachData && typeof d.heyreachData === 'object' && !d.heyreachData.error) {
    heyreachItems.push(d.heyreachData);
  }
  if (d.instantlyLifetimeData) {
    try { instantlyLifetimeItems.push(JSON.parse(d.instantlyLifetimeData)); } catch(e) {}
  }
  if (d.heyreachLifetimeData) {
    try { heyreachLifetimeItems.push(JSON.parse(d.heyreachLifetimeData)); } catch(e) {}
  }
}

const norm = s => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

const findLifetimeItem = (campaignName, platform) => {
  const list = platform === 'instantly' ? instantlyLifetimeItems : heyreachLifetimeItems;
  return list.find(x => norm(x.campaign_name || x.campaignName || x.name) === norm(campaignName)) || null;
};

const sortByOrder = (arr, nameList) => {
  return [...arr].sort((a, b) => {
    const nameA = a.targetCampaignName || a.campaignName || '';
    const nameB = b.targetCampaignName || b.campaignName || '';
    const findIdx = (name, list) => {
      const nName = norm(name);
      let idx = list.findIndex(n => norm(n) === nName);
      if (idx === -1) idx = list.findIndex(n => nName.includes(norm(n)) || norm(n).includes(nName));
      return idx === -1 ? 999 : idx;
    };
    return findIdx(nameA, nameList) - findIdx(nameB, nameList);
  });
};

const getCleanCampaignName = (name) => {
  if (!name) return 'Unknown Campaign';
  let clean = name.replace(/^\[[^\]]+\]\s*/g, '');
  const clientPrefixRegex = new RegExp('^' + clientName.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&') + '\\s*-\\s*', 'i');
  clean = clean.replace(clientPrefixRegex, '');
  clean = clean.replace(/\s*[\(-]\s*(Email|LinkedIn|HeyReach|Instantly)[\)]?\s*$/gi, '');
  return clean.trim();
};

const sortedInstantly = sortByOrder(instantlyItems, instantlyCampaignNames);
const sortedHeyreach = sortByOrder(heyreachItems, heyReachCampaignNames);

// ── Renderers ────────────────────────────────────────────────

const renderReplies = (rh, isInstantly) => {
  const noReplyMsg = isInstantly
    ? '  No human replies received during this reporting window.'
    : '  No replies received during this reporting window.';

  if (!rh || !rh.hasReplies) return noReplyMsg;

  const lines = [];
  const replies = rh.replies || [];

  if (isInstantly) {
    lines.push('  *Total Replies:* ' + (rh.totalReplies ?? 0) + ' | *Human Replies:* ' + (rh.humanReplies ?? 0));
  } else {
    lines.push('  *Conversations With Replies:* ' + (rh.conversationsWithReplies ?? 0));
  }

  if (replies.length > 0) {
    replies.forEach(r => {
      const sentimentEmoji = r.sentiment === 'positive' ? '🟢' : r.sentiment === 'negative' ? '🔴' : '⚪';
      lines.push('  ' + sentimentEmoji + ' *' + (r.name || 'Prospect') + '* (' + (r.title || r.position || 'N/A') + ' @ ' + (r.company || 'N/A') + '):');
      lines.push('    "' + (r.replyText || r.text || '') + '"');
    });
  }

  return lines.join('\n');
};

const renderKeyInsightsOnly = (d) => {
  if (!d) return '';
  const ki = d.keyInsights || {};
  const lines = [];
  if (ki.whatsWorking && ki.whatsWorking.length) {
    lines.push("What's Working:");
    ki.whatsWorking.slice(0, 2).forEach(w => lines.push('• ' + w));
  }
  if (ki.areasToWatch && ki.areasToWatch.length) {
    lines.push('Areas to Watch:');
    ki.areasToWatch.slice(0, 2).forEach(a => lines.push('• ' + a));
  }
  return lines.join('\n');
};

// ── Build Document ────────────────────────────────────────────
const doc = [];

// Header
doc.push('📊 *' + clientName.toUpperCase() + ' // WEEKLY OUTBOUND REPORT*');
doc.push('📅 *Reporting Period:* ' + startDate + ' to ' + endDate);
if (campaignContext) {
  doc.push('💡 *Context:* ' + campaignContext);
}
doc.push('');

const campaignGroups = {};

sortedInstantly.forEach(d => {
  const cleanName = getCleanCampaignName(d.targetCampaignName || d.campaignName || 'Email Campaign');
  if (!campaignGroups[cleanName]) campaignGroups[cleanName] = { name: cleanName, instantly: [], heyreach: [] };
  campaignGroups[cleanName].instantly.push(d);
});

sortedHeyreach.forEach(d => {
  const cleanName = getCleanCampaignName(d.targetCampaignName || d.campaignName || 'LinkedIn Campaign');
  if (!campaignGroups[cleanName]) campaignGroups[cleanName] = { name: cleanName, instantly: [], heyreach: [] };
  campaignGroups[cleanName].heyreach.push(d);
});

// Print Active Campaigns list
doc.push('🟢 *Active Campaigns:*');
Object.keys(campaignGroups).forEach(name => {
  const platforms = [];
  if (campaignGroups[name].instantly.length > 0) platforms.push('Email');
  if (campaignGroups[name].heyreach.length > 0) platforms.push('LinkedIn');
  doc.push('• *' + name + '* (' + platforms.join(' + ') + ')');
});
doc.push('\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

// Print each campaign's detailed breakdown
Object.values(campaignGroups).forEach(group => {
  doc.push('🔥 *CAMPAIGN: ' + group.name.toUpperCase() + '*');

  // Instantly Email sub-section
  if (group.instantly.length > 0) {
    group.instantly.forEach(d => {
      doc.push('✉️ *Email Channel (Instantly)*');

      if (d.replyHighlights && d.replyHighlights.hasReplies) {
        doc.push('  *Notable Replies:*');
        doc.push(renderReplies(d.replyHighlights, true));
      }

      const insights = renderKeyInsightsOnly(d);
      if (insights) {
        doc.push(insights);
      }
      doc.push('');
    });
  }

  // HeyReach LinkedIn sub-section
  if (group.heyreach.length > 0) {
    group.heyreach.forEach(d => {
      doc.push('💼 *LinkedIn Channel (HeyReach)*');

      if (d.replyHighlights && d.replyHighlights.hasReplies) {
        doc.push('  *Notable Replies:*');
        doc.push(renderReplies(d.replyHighlights, false));
      }

      const insights = renderKeyInsightsOnly(d);
      if (insights) {
        doc.push(insights);
      }
      doc.push('');
    });
  }
  doc.push('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
});

// Executive synthesis placeholder (filled by Finalize Document)
doc.push('🧠 *EXECUTIVE READOUT*');
doc.push('{{COMBINED_READOUT}}');
doc.push('');
doc.push('*Note: The first number in the metrics represents the weekly reporting window, while the number in parentheses denotes lifetime data.*');
doc.push('📎 *[Weekly Outbound Metrics CSV Spreadsheet Attached below]*');

const documentText = doc.join('\n');

// ── CSV Generation Logic ──────────────────────────────────────
const csvRows = ['Campaign Name,Platform,"Emails Sent / Conn. Requests",Open/Acceptance Rate,LI Messages Sent,Reply Rate,Primary Verdict'];

sortedInstantly.forEach(d => {
  const cleanName = getCleanCampaignName(d.targetCampaignName || d.campaignName || 'Email Campaign');
  const lt = findLifetimeItem(d.targetCampaignName || d.campaignName || '', 'instantly');
  const s = d.performanceScorecard || {};
  const os = lt ? (lt.performanceScorecard || lt.overallStats || lt) : {};
  const wLeads = s.totalLeads ?? 0;
  const ltLeads = os.leads_count ?? 0;
  const wOpen = s.openRate ?? '0.00%';
  const ltSent = os.emails_sent_count ?? 0;
  const ltOpen = ltSent > 0 ? ((os.open_count_unique ?? 0) / ltSent * 100).toFixed(2) + '%' : '0.00%';
  const wReply = s.replyRate ?? '0.00%';
  const ltReply = ltSent > 0 ? ((os.reply_count_unique ?? 0) / ltSent * 100).toFixed(2) + '%' : '0.00%';
  const verdict = d.keyInsights ? d.keyInsights.verdict || 'N/A' : 'N/A';

  const row = [
    `"${cleanName.replace(/"/g, '""')}"`,
    'Email',
    `"${wLeads} (${ltLeads})"`,
    `"${wOpen} (${ltOpen})"`,
    'N/A',
    `"${wReply} (${ltReply})"`,
    `"${verdict.replace(/"/g, '""')}"`
  ];
  csvRows.push(row.join(','));
});

sortedHeyreach.forEach(d => {
  const cleanName = getCleanCampaignName(d.targetCampaignName || d.campaignName || 'LinkedIn Campaign');
  const lt = findLifetimeItem(d.targetCampaignName || d.campaignName || '', 'heyreach');
  const s = d.performanceScorecard || {};
  const os = lt ? (lt.performanceScorecard || lt.overallStats || {}) : {};
  const wSent = s.connectionRequestsSent ?? 0;
  const ltSent = os.connectionsSent ?? os.connections_sent ?? 0;
  const wAcceptRate = s.connectionAcceptanceRate ?? '0.00%';
  const ltAcceptRate = os.connectionAcceptanceRate ? (parseFloat(os.connectionAcceptanceRate) * 100).toFixed(2) + '%' : '0.00%';
  const wMsgs = s.messagesSent ?? 0;
  const ltMsgs = os.totalMessageStarted ?? os.messagesSent ?? os.messages_sent ?? 0;
  const wReplyRate = s.messageReplyRate ?? '0.00%';
  const ltReplyRate = os.messageReplyRate ? (parseFloat(os.messageReplyRate) * 100).toFixed(2) + '%' : '0.00%';
  const verdict = d.keyInsights ? d.keyInsights.verdict || 'N/A' : 'N/A';

  const row = [
    `"${cleanName.replace(/"/g, '""')}"`,
    'LinkedIn',
    `"${wSent} (${ltSent})"`,
    `"${wAcceptRate} (${ltAcceptRate})"`,
    `"${wMsgs} (${ltMsgs})"`,
    `"${wReplyRate} (${ltReplyRate})"`,
    `"${verdict.replace(/"/g, '""')}"`
  ];
  csvRows.push(row.join(','));
});

const csvString = csvRows.join('\n');
const binaryData = Buffer.from(csvString, 'utf-8').toString('base64');

const campaignSummaries = [
  ...sortedInstantly.map(d => ({
    platform: 'Instantly',
    label: d.targetCampaignName || d.campaignName || '',
    verdict: d.keyInsights ? d.keyInsights.verdict || null : null,
    summary: d.executiveSummary || null,
    topSignals: d.replyHighlights ? (d.replyHighlights.sentimentBreakdown || null) : null
  })),
  ...sortedHeyreach.map(d => ({
    platform: 'HeyReach',
    label: d.targetCampaignName || d.campaignName || '',
    verdict: d.keyInsights ? d.keyInsights.verdict || null : null,
    summary: d.executiveSummary || null,
    topSignals: d.replyHighlights ? (d.replyHighlights.sentimentBreakdown || null) : null
  }))
];

const instantlyCampaignName = sortedInstantly.map(c => c.targetCampaignName || c.campaignName || '').filter(Boolean).join(', ') || '(none)';
const heyreachCampaignName = sortedHeyreach.map(c => c.targetCampaignName || c.campaignName || '').filter(Boolean).join(', ') || '(none)';

return [{
  json: {
    documentText,
    campaignSummaries,
    clientName,
    startDate,
    endDate,
    campaignContext,
    instantlyCampaignName,
    heyreachCampaignName,
    csvByteLength: Buffer.byteLength(csvString, 'utf-8')
  },
  binary: {
    data: {
      data: binaryData,
      mimeType: 'text/csv',
      fileName: `${clientName.toLowerCase().replace(/[^a-z0-9]/g, '_')}_weekly_outbound_metrics.csv`
    }
  }
}];

