const item = $json.instantlyData || {};
const scorecard = item.performanceScorecard || {};
const keyInsights = item.keyInsights || {};
const overview = item.campaignOverview || {};

const cleanPct = (val) => {
  if (val == null) return null;
  const num = parseFloat(String(val).replace(/%/g, ''));
  return isNaN(num) ? null : Math.round(num);
};

const sent = scorecard.emailsSent || 0;
const replyRate = cleanPct(scorecard.replyRate) || 0;
const reply = Math.round((replyRate / 100) * sent);

const weeklyItems = $('Get Campaign Analytics').all();
const matchedWeekly = weeklyItems.find(x => x.json.campaign_id === item.campaignOverview?.campaignId || x.json.campaign_name === item.campaignName || x.json.campaign_id === item.campaignName);
const open = matchedWeekly ? (matchedWeekly.json.open_count_unique ?? 0) : null;

const bounceRate = cleanPct(scorecard.bounceRate);
const bounce = bounceRate != null ? Math.round((bounceRate / 100) * sent) : null;

const windowStr = overview.reportingWindow || '';
const dates = windowStr.split(' to ');
const start = dates[0] || $json.startDate;
const end = dates[1] || $json.endDate;

// Fetch lifetime metrics
