} catch(e) {}

return [{
  json: {
    client_name: $json.clientName,
    campaign_id: item.campaignOverview?.campaignId || item.campaignName || 'unknown_campaign',
    campaign_name: item.campaignName || 'Unknown Campaign',
    platform: 'instantly',
    reporting_window_start: start,
    reporting_window_end: end,
    sent_count: sent,
    reply_count: reply,
    open_count: open,
    bounce_count: bounce,
    lifetime_sent_count: lifetimeSent,
    lifetime_reply_count: lifetimeReply,
    lifetime_open_count: lifetimeOpen,
    lifetime_bounce_count: lifetimeBounce,
    verdict: keyInsights.verdict || null,
    recommendations: keyInsights.areasToWatch || [],
    raw_ai_insights: item.executiveSummary || null
  }
}];

const item = $json.heyreachData || {};
