// Memory-safe accumulator: carries counts + repliers only (never full lead payloads)
let prev = null;
try {
  prev = $('Check Loop End').item.json;
} catch (e) {
  try {
    prev = $('Init Leads Pagination').item.json;
  } catch (err) {
    prev = null;
  }
}

const inputItems = $input.all();
const newItems = inputItems.map(i => i.json.items).flat().filter(Boolean);
const nextCursor = inputItems[0]?.json?.next_starting_after || null;

const totalLeads = ((prev && prev.totalLeads) || 0) + newItems.length;
const withReplies = ((prev && prev.withReplies) || []).concat(
  newItems
    .filter(l => l.email_reply_count > 0)
    .map(l => ({
      email: l.email,
      name: `${l.first_name} ${l.last_name}`,
      company: l.company_name,
      jobTitle: l.payload?.jobTitle,
      replyCount: l.email_reply_count
    }))
);

const hasMore = !!nextCursor && totalLeads < 5000;
const campaignId = $('Init Leads Pagination').item.json.campaignId;

return [{
  json: {
    campaignId,
    totalLeads,
    withReplies,
    starting_after: nextCursor,
    hasMore
  }
}];

const snapshotItems = $('Fetch Client History').all();
let historyArray = [];
try {
  const rawText = snapshotItems[0]?.json || [];
  historyArray = Array.isArray(rawText) ? rawText : (rawText.data ? (typeof rawText.data === 'string' ? JSON.parse(rawText.data) : rawText.data) : []);
} catch(e) {
  historyArray = [];
}

if (!Array.isArray(historyArray) || historyArray.length === 0) {
  return [{ json: { is_empty_history: true } }];
}
return historyArray.map(item => ({ json: item }));

