// Aggregate all active clients into one reminder message for Jackson
const clients = $input.all().map(i => i.json.client_name).filter(Boolean);
const text = `⏰ *FF Outbound Reporting Reminder*

The automated outbound reports will run on Monday at 9:00 AM for ${clients.length} active client${clients.length === 1 ? '' : 's'}:
${clients.map(c => `• ${c}`).join('
')}

If there is any strategic context for these campaigns (e.g. paused sequences, list cleaning, testing new ICP), please log it before Monday using \`/log-context\` so the AI analyst includes it!`;
return [{ json: { text } }];

const kbItems = $('Fetch Messaging KB').all();
let kbArray = [];
try {
  const rawText = kbItems[0]?.json || [];
  kbArray = Array.isArray(rawText) ? rawText : (rawText.data ? (typeof rawText.data === 'string' ? JSON.parse(rawText.data) : rawText.data) : []);
} catch(e) {
  kbArray = [];
}

if (!Array.isArray(kbArray) || kbArray.length === 0) {
  return [{ json: { is_empty_kb: true } }];
}
return kbArray.map(item => ({ json: item }));

const item = $json.instantlyData || {};
const keyInsights = item.keyInsights || {};

const approachParts = [];
if (keyInsights.primarySignal) approachParts.push(keyInsights.primarySignal);
if (Array.isArray(keyInsights.whatsWorking) && keyInsights.whatsWorking.length) {
  approachParts.push('Working: ' + keyInsights.whatsWorking.join('; '));
}
if (Array.isArray(keyInsights.areasToWatch) && keyInsights.areasToWatch.length) {
  approachParts.push('Watching: ' + keyInsights.areasToWatch.join('; '));
}

return [{
  json: {
    client_name: $json.clientName,
    campaign_id: item.campaignOverview?.campaignId || item.campaignName || 'unknown_campaign',
    campaign_name: item.campaignName || $json.targetCampaignName || 'Unknown Campaign',
    platform: 'instantly',
    icp_segment: null,
    approach: approachParts.join(' | ') || null,
    outcome: item.executiveSummary || null,
    verdict: keyInsights.verdict || null,
    week_of: $json.startDate || null
  }
}];

const item = $json.heyreachData || {};
const keyInsights = item.keyInsights || {};

const approachParts = [];
if (keyInsights.primarySignal) approachParts.push(keyInsights.primarySignal);
if (Array.isArray(keyInsights.whatsWorking) && keyInsights.whatsWorking.length) {
  approachParts.push('Working: ' + keyInsights.whatsWorking.join('; '));
}
if (Array.isArray(keyInsights.areasToWatch) && keyInsights.areasToWatch.length) {
  approachParts.push('Watching: ' + keyInsights.areasToWatch.join('; '));
}

return [{
  json: {
    client_name: $json.clientName,
    campaign_id: item.campaignConfig?.id || item.campaignName || 'unknown_campaign',
    campaign_name: item.campaignName || $json.targetCampaignName || 'Unknown Campaign',
    platform: 'heyreach',
    icp_segment: null,
    approach: approachParts.join(' | ') || null,
    outcome: item.executiveSummary || null,
    verdict: keyInsights.verdict || null,
    week_of: $json.startDate || null
  }
}];
